cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 3D convolution for kernel (K, K, 1), stride 1, dilation 1, groups 1.
// The input is treated as N*D independent 2D convolutions over the (H, W) plane,
// because the kernel extent along the last dimension is 1.
// Optimization: the (Wout, Dout) plane of each output row is treated as one
// flat contiguous dimension (D is the innermost, contiguous tensor dim).
// Each block owns TWF=64 consecutive flat (w,d) outputs per row, so every
// warp stores 32 fully-consecutive floats (128B transactions) instead of
// short Dout-long runs scattered across columns, and the staged input
// loads follow the same flat order. This directly attacks the dominant
// DRAM cost (the output-volume-dominated stores) of this conv shape.
template <int K>
__global__ void __launch_bounds__(256, 2) conv3d_kk1_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int Cin, int H, int Wd, int D,
    int Cout, int Hout, int Wout, int Dout,
    int padding, int IWt)
{
  constexpr int TH      = 32;
  constexpr int TWF     = 64;   // flat (w,d) outputs per block per row
  constexpr int COT     = 4;
  constexpr int Threads = 256;
  constexpr int IH      = TH + K - 1;
  // 256 threads = TWF flat positions x 4 row groups; each thread owns TR = 8
  // consecutive output rows for one flat (column, depth) position.
  constexpr int TR = TH / (Threads / TWF);
  const int tid = threadIdx.x;
  // Global strides for contiguous (N, C, H, W, D) layout
  const int64_t sXn = (int64_t)Cin * H * Wd * D;
  const int64_t sXc = (int64_t)H * Wd * D;
  const int64_t sXh = (int64_t)Wd * D;
  const int64_t sXw = (int64_t)D;
  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;
  // Tile coordinates: blockIdx.x covers (row tiles) x (flat w*d tiles)
  const int row_flat = Wout * Dout;
  const int tiles_f  = (row_flat + TWF - 1) / TWF;
  const int tile_y   = blockIdx.x / tiles_f;
  const int tile_x   = blockIdx.x - tile_y * tiles_f;
  const int oh0      = tile_y * TH;
  const int f0       = tile_x * TWF;
  const int w_lo     = f0 / Dout;  // first output column this block touches
  // blockIdx.y covers one batch item; the input tile is reused across all
  // output-channel groups by advancing co0 sequentially below.
  const int n = blockIdx.y;
  Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn),
                          make_shape(Cout, Hout, Wout, Dout),
                          make_stride(sYc, sYh, sYw, Int<1>{}));
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn),
                          make_shape(Cin, H, Wd, D),
                          make_stride(sXc, sXh, sXw, Int<1>{}));
  Tensor mW = make_tensor(make_gmem_ptr(Wt),
                          make_shape(Cout, Cin, Int<K>{}, Int<K>{}),
                          make_stride((int64_t)Cin * (K * K), Int<K * K>{}, Int<K>{}, Int<1>{}));
  // Thread mapping: flat (w,d) position is fastest so that consecutive
  // threads (and hence each warp) map to consecutive global addresses for
  // both staged loads and output stores.
  const int sub   = tid & (TWF - 1);
  const int tq    = tid / TWF;
  const int f     = f0 + sub;
  const int ow    = f / Dout;
  const int d_out = f - ow * Dout;
  const int w_off = ow - w_lo;  // column base inside the smem tile
  const bool p_valid = (ow < Wout) && (oh0 + tq * TR < Hout);
  // Dynamic shared memory: input tile (all Dout depths, d-fastest layout)
  // followed by one COT output-channel weight group.
  extern __shared__ float smem[];
  float* sX_ptr = smem;
  float* sW_ptr = smem + (size_t)Cin * IH * IWt * Dout;
  Tensor sX = make_tensor(make_smem_ptr(sX_ptr),
                          make_shape(Cin, Int<IH>{}, IWt, Dout),
                          make_stride((int64_t)IH * IWt * Dout, (int64_t)IWt * Dout, (int64_t)Dout, Int<1>{}));
  Tensor sW = make_tensor(make_smem_ptr(sW_ptr),
                          make_shape(Int<COT>{}, Cin, Int<K>{}, Int<K>{}),
                          make_stride(Cin * (K * K), Int<K * K>{}, Int<K>{}, Int<1>{}));
  // Stage the input tile cooperatively (zero-filled halo). Linear thread
  // traversal with d fastest matches the global (w,d) contiguity, so the
  // staged global loads are coalesced too.
  const int sX_total = Cin * IH * IWt * Dout;
  for (int idx = tid; idx < sX_total; idx += Threads) {
    int d  = idx % Dout;
    int iw = (idx / Dout) % IWt;
    int ih = (idx / (Dout * IWt)) % IH;
    int ci = idx / (Dout * IWt * IH);
    int gh = oh0 + ih - padding;
    int gw = w_lo + iw - padding;
    int d_in = d - padding;
    float v = 0.f;
    if ((unsigned)gh < (unsigned)H && (unsigned)gw < (unsigned)Wd &&
        (unsigned)d_in < (unsigned)D) {
      v = mX(ci, gh, gw, d_in);
    }
    sX(ci, ih, iw, d) = v;
  }
  __syncthreads(); // input tile is resident; reuse it for every output-channel group
  const int sW_total = COT * Cin * K * K;
  for (int co0 = 0; co0 < Cout; co0 += COT) {
    for (int idx = tid; idx < sW_total; idx += Threads) {
      int kw = idx % K;
      int kh = (idx / K) % K;
      int ci = (idx / (K * K)) % Cin;
      int co = idx / (K * K * Cin);
      int co_g = co0 + co;
      float v = 0.f;
      if (co_g < Cout) v = mW(co_g, ci, kh, kw);
      sW(co, ci, kh, kw) = v;
    }
    __syncthreads();
    if (p_valid) {
      // Accumulate COT output channels for TR output rows at one flat
      // (column, depth) position: TR x COT = 8 x 4 = 32 accumulators.
      float acc[COT][TR];
      #pragma unroll
      for (int co = 0; co < COT; ++co) {
        int co_g = co0 + co;
        float bv = (B != nullptr && co_g < Cout) ? B[co_g] : 0.f;
        #pragma unroll
        for (int r = 0; r < TR; ++r) {
          acc[co][r] = bv;
        }
      }
      for (int ci = 0; ci < Cin; ++ci) {
        #pragma unroll
        for (int kh = 0; kh < K; ++kh) {
          #pragma unroll
          for (int kw = 0; kw < K; ++kw) {
            float xv[TR];
            #pragma unroll
            for (int r = 0; r < TR; ++r) {
              xv[r] = sX(ci, tq * TR + r + kh, w_off + kw, d_out);
            }
            #pragma unroll
            for (int co = 0; co < COT; ++co) {
              float wv = sW(co, ci, kh, kw);
              #pragma unroll
              for (int r = 0; r < TR; ++r) {
                acc[co][r] = fmaf(xv[r], wv, acc[co][r]);
              }
            }
          }
        }
      }
      // Fully coalesced streaming stores: consecutive threads hold
      // consecutive flat (w,d) addresses, so each warp writes 128
      // contiguous bytes per (channel, row) store.
      #pragma unroll
      for (int co = 0; co < COT; ++co) {
        int co_g = co0 + co;
        if (co_g < Cout) {
          #pragma unroll
          for (int r = 0; r < TR; ++r) {
            int oh = oh0 + tq * TR + r;
            if (oh < Hout) __stwt(&mY(co_g, oh, ow, d_out), acc[co][r]);
          }
        }
      }
    }
    __syncthreads(); // all threads are done before the next weight-group overwrite
  }
}

namespace {

template <int K>
void launch_conv3d_kk1(const float* X, const float* Wt, const float* B, float* Y,
                       int N, int Cin, int H, int Wd, int D,
                       int Cout, int Hout, int Wout, int Dout,
                       int padding, cudaStream_t stream)
{
  constexpr int TH  = 32;
  constexpr int TWF = 64;   // flat (w,d) outputs per block per row
  constexpr int COT = 4;
  constexpr int IH  = TH + K - 1;
  // Tile the contiguous (Wout, Dout) plane of each row as one flat dim so
  // that warps read/write fully consecutive global addresses.
  const int row_flat = Wout * Dout;
  const int tiles_f  = (row_flat + TWF - 1) / TWF;
  const int tiles_y  = (Hout + TH - 1) / TH;
  // Input columns touched by a flat tile: <= ceil(TWF/Dout) + K - 1 (+1 slack).
  const int IWt      = (TWF + Dout - 1) / Dout + K;
  dim3 block(256);
  dim3 grid(tiles_f * tiles_y, N, 1);
  size_t smem = ((size_t)Cin * IH * IWt * Dout + (size_t)COT * Cin * K * K) * sizeof(float);
  if (smem > 48 * 1024) {
    cudaFuncSetAttribute(conv3d_kk1_kernel<K>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem);
  }
  conv3d_kk1_kernel<K><<<grid, block, smem, stream>>>(
      X, Wt, B, Y, Cin, H, Wd, D, Cout, Hout, Wout, Dout, padding, IWt);
}

} // namespace

torch::Tensor conv3d_kk1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> b,
                                 int64_t stride,
                                 int64_t padding,
                                 int64_t dilation,
                                 int64_t groups)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, D]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin, K, K, 1]");
  TORCH_CHECK(groups == 1, "only groups == 1 is supported");
  TORCH_CHECK(stride == 1, "only stride == 1 is supported");
  TORCH_CHECK(dilation == 1, "only dilation == 1 is supported");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  const int64_t K = w.size(2);
  TORCH_CHECK(w.size(3) == K && w.size(4) == 1, "kernel must be (K, K, 1)");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N    = x_c.size(0);
  const int64_t Cin  = x_c.size(1);
  const int64_t H    = x_c.size(2);
  const int64_t Wd   = x_c.size(3);
  const int64_t D    = x_c.size(4);
  const int64_t Cout = w_c.size(0);
  TORCH_CHECK(w_c.size(1) == Cin, "w.size(1) must equal in_channels");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be a CUDA float32 tensor");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  const int64_t Hout = H + 2 * padding - K + 1;
  const int64_t Wout = Wd + 2 * padding - K + 1;
  const int64_t Dout = D + 2 * padding;
  TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "invalid output size");

  auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  const float* Xp  = x_c.data_ptr<float>();
  const float* Wp  = w_c.data_ptr<float>();
  float*       Yp  = y.data_ptr<float>();

  switch (K) {
    case 1:
      launch_conv3d_kk1<1>(Xp, Wp, b_ptr, Yp, (int)N, (int)Cin, (int)H, (int)Wd, (int)D,
                           (int)Cout, (int)Hout, (int)Wout, (int)Dout, (int)padding, stream);
      break;
    case 3:
      launch_conv3d_kk1<3>(Xp, Wp, b_ptr, Yp, (int)N, (int)Cin, (int)H, (int)Wd, (int)D,
                           (int)Cout, (int)Hout, (int)Wout, (int)Dout, (int)padding, stream);
      break;
    case 5:
      launch_conv3d_kk1<5>(Xp, Wp, b_ptr, Yp, (int)N, (int)Cin, (int)H, (int)Wd, (int)D,
                           (int)Cout, (int)Hout, (int)Wout, (int)Dout, (int)padding, stream);
      break;
    case 7:
      launch_conv3d_kk1<7>(Xp, Wp, b_ptr, Yp, (int)N, (int)Cin, (int)H, (int)Wd, (int)D,
                           (int)Cout, (int)Hout, (int)Wout, (int)Dout, (int)padding, stream);
      break;
    default:
      TORCH_CHECK(false, "unsupported kernel size K = ", K, " (supported: 1, 3, 5, 7)");
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kk1_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
